const samples = await IO.loadMNIST();
const sampleA = samples[31];
const sampleB = samples[87];
const coordinates = Array.from(sampleA, (_, i) => [(i % 28) / 27, 1 - Math.floor(i / 28) / 27]);
const trainXs = [];
const trainA = [];
const trainB = [];
for (let i = 0; i < sampleA.length; i++) {
    const row = Math.floor(i / 28);
    const column = i % 28;
    if (row % 2 === 0 && column % 2 === 0) {
        trainXs.push(coordinates[i]);
        trainA.push(sampleA[i]);
        trainB.push(sampleB[i]);
    }
}

let sigma = 0.06;
let lambda = 0.01;
let t = 0;
let predictionsA;
let predictionsB;
const image = IO.paintMNIST([sampleA, new Float32Array(sampleA.length), sampleB]);
const updateImage = () => {
    const interpolation = Float32Array.from(coordinates, (_, i) => {
        const value = (1 - t) * predictionsA[i] + t * predictionsB[i];
        return Math.max(0, Math.min(1, value));
    });
    image.update([sampleA, interpolation, sampleB]);
};
const fit = () => {
    const currentSigma = sigma;
    const gaussianKernel = (a, b) => {
        const dx = a[0] - b[0];
        const dy = a[1] - b[1];
        return Math.exp(-(dx * dx + dy * dy) / (2 * currentSigma * currentSigma));
    };
    const options = {kernelFn: gaussianKernel, lambda};
    const modelA = KernelRegression.new(trainXs, trainA, options).fit();
    const modelB = KernelRegression.new(trainXs, trainB, options).fit();
    predictionsA = coordinates.map(point => modelA.predict(point));
    predictionsB = coordinates.map(point => modelB.predict(point));
    updateImage();
};
fit();

let updateTimer;
const update = () => {
    clearTimeout(updateTimer);
    updateTimer = setTimeout(fit, 150);
};
const ui = IO.UI(
    {type: "canvas", value: () => image},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 0.01, value: t,
        onChange: value => { t = value; updateImage(); },
    })},
    {type: "slider", value: () => ({
        title: "Sigma:", min: 0.02, max: 0.2, step: 0.01, value: sigma,
        onChange: value => { sigma = value; update(); },
    })},
    {type: "slider", value: () => ({
        title: "Lambda:", min: 0.01, max: 0.5, step: 0.01, value: lambda,
        onChange: value => { lambda = value; update(); },
    })},
);
ui;
